package com.cpf.integration.fixedlength;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class CpfFixedLengthCodecTest{@Test void roundTrip(){var l=new CpfFixedLengthLayout("T",8,StandardCharsets.US_ASCII,List.of(new CpfFixedLengthField("id",0,3,CpfFixedLengthField.Alignment.RIGHT,'0',true),new CpfFixedLengthField("name",3,5,CpfFixedLengthField.Alignment.LEFT,' ',true)));var c=new CpfFixedLengthCodec(l);assertThat(c.decode(c.encode(Map.of("id","7","name","AB")))).containsEntry("id","7").containsEntry("name","AB");}}
